    "board.stm32f103vbt6": ["LQFP-100 · Cortex-M3 · 72 MHz", "LQFP-100 · Cortex-M3 · 72 MHz"],
    "noMcuPad": ["Bu konnektör kontağı için doğrudan MCU bacağı eşlemesi yok.", "This connector contact has no direct MCU pad mapping."],
